<body>

<div class="card">
    <h2>門市月銷售量趨勢</h2>
    <div class="chart-container" id="chart">
        <svg id="svg-canvas" viewBox="0 0 800 400" preserveAspectRatio="none"></svg>
    </div>
    <div class="legend" id="legend"></div>
</div>

<script>
    const rawData = `月份	門市A	門市B	門市C
1月	1,200	950	800
2月	1,350	1,020	760
3月	1,500		910
4月	1,420	1,150	990
5月	1,680	1,200	1,050
6月	1,750	1,310	1,100
合計	8,900	5,630	5,610`;

    function initChart() {
        const rows = rawData.trim().split('\n');
        const headers = rows[0].split('\t').slice(1);
        const months = [];
        const storeData = headers.map(() => []);

        // 解析資料 (跳過標題與合計)
        for (let i = 1; i < rows.length - 1; i++) {
            const cols = rows[i].split('\t');
            months.push(cols[0]);
            for (let j = 0; j < headers.length; j++) {
                const rawVal = cols[j + 1] ? cols[j + 1].trim() : "";
                const val = rawVal === "" ? null : parseInt(rawVal.replace(/,/g, ''));
                storeData[j].push(val);
            }
        }

        const width = 800;
        const height = 400;
        const padding = 50;
        const chartW = width - padding * 2;
        const chartH = height - padding * 2;

        const svg = document.getElementById('svg-canvas');
        const allNums = storeData.flat().filter(v => v !== null);
        const maxVal = Math.ceil(Math.max(...allNums) / 500) * 500;
        const colors = ['#007AFF', '#34C759', '#FF9500'];

        let gridHTML = '';
        for (let i = 0; i <= 5; i++) {
            const y = height - padding - (i * chartH / 5);
            const label = Math.round(maxVal * i / 5);
            gridHTML += `<line class="grid-line" x1="${padding}" y1="${y}" x2="${width - padding}" y2="${y}" />`;
            gridHTML += `<text class="label" x="${padding - 10}" y="${y + 5}" text-anchor="end">${label}</text>`;
        }

        months.forEach((m, i) => {
            const x = padding + (i * chartW / (months.length - 1));
            gridHTML += `<text class="label" x="${x}" y="${height - padding + 25}" text-anchor="middle">${m}</text>`;
        });

        let elementsHTML = '';
        let legendHTML = '';

        storeData.forEach((data, storeIdx) => {
            let pathData = "";
            let lastValid = false;

            data.forEach((val, i) => {
                const x = padding + (i * chartW / (months.length - 1));

                if (val !== null) {
                    const y = height - padding - (val / maxVal * chartH);
                    if (!lastValid) {
                        pathData += `M ${x},${y} `;
                    } else {
                        pathData += `L ${x},${y} `;
                    }
                    elementsHTML += `<circle class="point" cx="${x}" cy="${y}" stroke="${colors[storeIdx]}" />`;
                    lastValid = true;
                } else {
                    lastValid = false;
                    // 標示無資料
                    elementsHTML += `<text class="no-data-text" x="${x}" y="${height - padding - 20}" text-anchor="middle">無資料</text>`;
                }
            });

            elementsHTML += `<path class="line path-animated" d="${pathData}" stroke="${colors[storeIdx]}" id="path-${storeIdx}" />`;

            legendHTML += `
                <div class="legend-item">
                    <div class="legend-color" style="background:${colors[storeIdx]}"></div>
                    <span>${headers[storeIdx]}</span>
                </div>
            `;
        });

        svg.innerHTML = gridHTML + elementsHTML;
        document.getElementById('legend').innerHTML = legendHTML;

        // 執行路徑動畫
        headers.forEach((_, i) => {
            const path = document.getElementById(`path-${i}`);
            if (path) {
                const length = path.getTotalLength();
                path.style.strokeDasharray = length;
                path.style.strokeDashoffset = length;
                path.getBoundingClientRect(); // 觸發重繪
                path.style.animation = "draw 2s ease-out forwards";
            }
        });
    }

    window.onload = initChart;
</script>

